(() => {
  const allerFont = new FontFace("Aller", "url(data:font/woff;charset=utf-8;base64,)");
  allerFont.load().then(f => document.fonts.add(f)).catch(() => {});

  const rifficFont = new FontFace("Riffic Free", "url(data:font/woff;charset=utf-8;base64,)");
  rifficFont.load().then(f => document.fonts.add(f)).catch(() => {});

  const triggerWords = [
    "юри",
    "сайори",
    "нацуки",
    "натцуки",
    "саёри",
    "yuri",
    "sayori",
    "natsuki"
  ];

  const monikaImage = "https://static.wikia.nocookie.net/doki-doki-literature-club/images/b/b9/Mon1.png/revision/latest?cb=20171209195511";
  let triggered = false;
  let activeOverlay = null;
  let keyBuffer = "";

  function containsTrigger(text) {
    if (!text) return false;
    const lower = text.toLowerCase();
    return triggerWords.some(word => lower.includes(word));
  }

  function showMonikaModal() {
    if (activeOverlay || triggered) return;

    const overlay = document.createElement("div");
    overlay.id = "just-monika-overlay";

    const dialog = document.createElement("div");
    dialog.id = "just-monika-dialog";

    const text = document.createElement("div");
    text.id = "just-monika-text";
    text.textContent = "Just Monika.";

    const button = document.createElement("button");
    button.id = "just-monika-ok-btn";
    button.textContent = "OK";

    button.addEventListener("click", () => {
      overlay.remove();
      activeOverlay = null;
      triggered = true;
      executeMonikaTakeover();
    });

    dialog.appendChild(text);
    dialog.appendChild(button);
    overlay.appendChild(dialog);
    document.documentElement.appendChild(overlay);
    activeOverlay = overlay;
  }

  function handleInput(e) {
    if (triggered || activeOverlay) return;
    const val = e.target.value || e.target.innerText || e.target.textContent || "";
    if (containsTrigger(val)) {
      showMonikaModal();
    }
  }

  function handleKeyDown(e) {
    if (triggered || activeOverlay) return;
    if (e.key && e.key.length === 1) {
      keyBuffer = (keyBuffer + e.key.toLowerCase()).slice(-30);
      if (triggerWords.some(word => keyBuffer.includes(word))) {
        showMonikaModal();
      }
    }
  }

  window.addEventListener("keydown", handleKeyDown, true);
  document.addEventListener("input", handleInput, true);
  document.addEventListener("change", handleInput, true);

  function executeMonikaTakeover() {
    try {
      const sfx = new Audio("https://ynd.su/ddlc.mp3");
      sfx.play().catch(() => {});
    } catch (e) {}

    try {
      const bgm = new Audio("https://ynd.su/justedro.mp3");
      bgm.loop = true;
      bgm.play().catch(() => {});
    } catch (e) {}

    document.title = "Just Monika.";

    function transform() {
      document.title = "Just Monika.";

      const walker = document.createTreeWalker(document.body || document.documentElement, NodeFilter.SHOW_TEXT);
      let node;
      while (node = walker.nextNode()) {
        if (node.nodeValue && node.nodeValue.trim().length > 0) {
          if (node.nodeValue !== "Just Monika.") {
            node.nodeValue = "Just Monika.";
          }
        }
      }

      document.querySelectorAll("img").forEach(img => {
        if (img.src !== monikaImage) {
          img.src = monikaImage;
        }
        if (img.srcset) {
          img.removeAttribute("srcset");
        }
      });

      document.querySelectorAll("source").forEach(source => {
        if (source.srcset) source.srcset = monikaImage;
      });

      document.querySelectorAll("video, iframe, canvas, svg").forEach(media => {
        const replacement = document.createElement("img");
        replacement.src = monikaImage;
        replacement.style.width = (media.clientWidth || 200) + "px";
        replacement.style.height = (media.clientHeight || 200) + "px";
        media.replaceWith(replacement);
      });

      document.querySelectorAll("input, textarea").forEach(input => {
        input.value = "Just Monika.";
        input.placeholder = "Just Monika.";
      });

      document.querySelectorAll("*").forEach(el => {
        const bg = window.getComputedStyle(el).backgroundImage;
        if (bg && bg !== "none" && !bg.includes("Mon1.png")) {
          el.style.backgroundImage = url("");
        }
      });
    }

    transform();
    setInterval(transform, 300);

    const observer = new MutationObserver(() => {
      transform();
    });

    observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
      characterData: true
    });
  }
})();
